'use strict';
// Opt-in replacement for the public Kalender Ekonomi panel only.
// The iframe URL must be generated by Investing.com's official widget tool
// after the website owner accepts the provider's terms. No scraping or proxying.
const RELEASE='mm-investing-calendar-20261118-v1';
const SCRIPT_ID='mm-investing-calendar-script';
const STYLE_ID='mm-investing-calendar-style';

function approvedInvestingUrl(raw){
  if(typeof raw!=='string'||raw.length>8192)return null;
  // Support both the generated iframe src and the complete official embed snippet.
  // Never inject third-party HTML; only extract the src and verify its origin/options.
  const source=raw.trim();
  let candidate=source;
  if(/^<iframe\b/i.test(source)){
    const tag=source.match(/^<iframe\b[^>]*>/i);
    if(!tag)return null;
    const src=tag[0].match(/\bsrc\s*=\s*(["'])(.*?)\1/i);
    if(!src)return null;
    candidate=src[2].replace(/&amp;/gi,'&');
  }
  let url;
  try{url=new URL(candidate);}catch{return null;}
  if(url.protocol!=='https:'||url.hostname!=='sslecal2.investing.com'||
     url.port||url.username||url.password||url.pathname!=='/'||url.hash||!url.search)return null;
  // Require the exact user-requested defaults from the official Indonesian widget:
  // GMT+7 Bangkok/Hanoi/Jakarta = 27; High Impact only = 3.
  if(['timeZone','importance','calType','lang','countries','columns'].some(name=>url.searchParams.getAll(name).length!==1))return null;
  if(url.searchParams.get('timeZone')!=='27'||url.searchParams.get('importance')!=='3')return null;
  if(!['week','day'].includes(url.searchParams.get('calType')))return null;
  if(!/^\d+$/.test(url.searchParams.get('lang')||''))return null;
  const countries=new Set((url.searchParams.get('countries')||'').split(','));
  if(!['5','72','4','35'].every(id=>countries.has(id)))return null;
  const columns=new Set((url.searchParams.get('columns')||'').split(','));
  if(!['exc_currency','exc_importance','exc_actual','exc_forecast','exc_previous'].every(id=>columns.has(id)))return null;
  return url.href;
}

const STYLE=`<style id="${STYLE_ID}">
body.mm-investing-calendar-on #app{background:#f7f8fc!important;color:#172334!important}
body.mm-investing-calendar-on .mm88-desk{background:#f7f8fc!important;color:#172334!important;max-width:none!important;width:100%!important;box-sizing:border-box!important;border:0!important;box-shadow:none!important;padding:0!important}
body.mm-investing-calendar-on .mm88-desk > :not(#mm-investing-calendar){display:none!important}
body:not(.mm-investing-calendar-on) #mm-investing-calendar{display:none!important}
body.mm-investing-calendar-on #mm-investing-calendar{display:block!important;box-sizing:border-box;width:min(100%,1180px);margin:18px auto 32px;padding:0 14px;font:inherit;color:#172334}
.mm-investing-calendar-head{display:flex;align-items:flex-start;justify-content:space-between;flex-wrap:wrap;gap:14px;margin-bottom:15px}
.mm-investing-calendar-head h1{font-size:clamp(21px,2.6vw,29px);font-weight:800;line-height:1.2;letter-spacing:-.035em;color:#172334;margin:0 0 7px}
.mm-investing-calendar-head p{font-size:13px;color:#667085;margin:0;line-height:1.65}
.mm-investing-calendar-badges{display:flex;gap:7px;flex-wrap:wrap;align-items:center}
.mm-investing-calendar-badges span{font-size:11px;line-height:1.4;font-weight:750;color:#995204;background:#fff5e7;border:1px solid #ffdba6;border-radius:999px;padding:5px 10px}
.mm-investing-calendar-badges span:first-child{color:#1f5b48;background:#eaf9f1;border-color:#c7ebd6}
.mm-investing-calendar-card{border:1px solid #e5e9f0;border-radius:16px;background:#fff;box-shadow:0 10px 30px rgba(22,33,48,.06);overflow:hidden}
.mm-investing-calendar-bar{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;padding:12px 15px;border-bottom:1px solid #edf0f4;background:#fff}
.mm-investing-calendar-bar strong{font-size:12px;font-weight:800;color:#2f3b4d}
.mm-investing-calendar-bar button{cursor:pointer;border:1px solid #dfe3eb;border-radius:9px;padding:7px 12px;background:#fff;font-size:12px;font-weight:700;color:#42526b}
.mm-investing-calendar-bar button:hover,.mm-investing-calendar-bar button:focus-visible{border-color:#e58b1c;color:#a95b00;outline-offset:2px}
.mm-investing-calendar-scroll{width:100%;max-width:100%;overflow-x:auto;overscroll-behavior-x:contain;background:#fff}
.mm-investing-calendar-scroll iframe{display:block;width:100%;min-width:650px;height:720px;border:0;background:#fff}
.mm-investing-calendar-foot{display:flex;justify-content:space-between;gap:8px 15px;flex-wrap:wrap;align-items:center;background:#fff;padding:13px 15px;border-top:1px solid #edf0f4;color:#667085;font-size:12px;line-height:1.6}
.mm-investing-calendar-foot a{color:#bb6300;font-weight:750;text-decoration:none}
.mm-investing-calendar-foot a:hover{text-decoration:underline}
.mm-investing-calendar-note{font-size:12px;color:#667085;line-height:1.7;margin:13px 2px 0}
.mm-investing-calendar-state{display:block;padding:10px 15px;background:#fffaf3;border-bottom:1px solid #ffe5ba;color:#88500a;font-size:12px;line-height:1.55;margin:0}
.mm-investing-calendar-actions{display:flex;flex-wrap:wrap;align-items:center;gap:7px}
.mm-investing-calendar-bar .mm-investing-calendar-back{color:#975003;border-color:#ffe0b1}
body.mm-investing-calendar-fallback #mm-investing-calendar{display:none!important}
@media(max-width:720px){body.mm-investing-calendar-on #mm-investing-calendar{padding:0 8px;margin:10px auto 22px}.mm-investing-calendar-scroll iframe{height:650px}.mm-investing-calendar-card{border-radius:12px}.mm-investing-calendar-head h1{font-size:22px}}
</style>`;

const CLIENT=String.raw`(function(){
'use strict';
const EMBED_URL=__MM_IFRAME_URL__;
const RELEASE='mm-investing-calendar-20261118-v1';
function isCalendar(){
 const active=document.querySelector('.navbtn.active,.navbtn.is-active');
 const selected=!!active && /kalender\s+ekonomi/i.test((active.dataset&&active.dataset.page)||active.textContent||'');
 const label=document.getElementById('toplabel');
 return selected || /^\/kalender-ekonomi(?:\/)?$/i.test(location.pathname) ||
  !!(label&&/kalender\s+ekonomi\s*$/i.test((label.textContent||'').trim()));
}
function createCalendar(){
 const section=document.createElement('section');section.id='mm-investing-calendar';section.setAttribute('aria-label','Kalender Ekonomi Investing.com');
 section.innerHTML='<div class="mm-investing-calendar-head"><div><h1>Kalender Ekonomi</h1><p>Pantau jadwal data ekonomi penting dan hasil rilis langsung.</p></div><div class="mm-investing-calendar-badges"><span>● Pembaruan otomatis</span><span>WIB · UTC+7</span><span>High Impact</span></div></div><div class="mm-investing-calendar-card"><div class="mm-investing-calendar-bar"><strong>KALENDER EKONOMI GLOBAL</strong><div class="mm-investing-calendar-actions"><button type="button" id="mm-investing-calendar-reload" aria-label="Muat ulang kalender">↻ Muat ulang</button><button type="button" class="mm-investing-calendar-back" id="mm-investing-calendar-legacy">Kalender sebelumnya</button></div></div><p class="mm-investing-calendar-state" id="mm-investing-calendar-state" role="status" aria-live="polite">Menghubungkan kalender Investing.com…</p><div class="mm-investing-calendar-scroll"><iframe id="mm-investing-calendar-frame" title="Kalender Ekonomi Investing.com, waktu WIB dan dampak tinggi" loading="eager" referrerpolicy="strict-origin-when-cross-origin"></iframe></div><div class="mm-investing-calendar-foot"><span>Data, jadwal, dan pembaruan disediakan Investing.com</span><a href="https://id.investing.com/economic-calendar/" target="_blank" rel="noopener noreferrer nofollow">Buka kalender lengkap di Investing.com ↗</a></div></div><p class="mm-investing-calendar-note">Tampilan pada ponsel dapat digeser ke samping. Filter dan zona waktu mengikuti konfigurasi widget resmi Investing.com; jadwal serta hasil rilis dapat berubah.</p>';
 const iframe=section.querySelector('iframe');
 const state=section.querySelector('#mm-investing-calendar-state');
 let loadTimeout=null;
 function setState(message){state.textContent=message;}
 function cancelTimer(){if(loadTimeout!==null){clearTimeout(loadTimeout);loadTimeout=null;}}
 function loadFrame(){
   cancelTimer();
   setState('Menghubungkan kalender Investing.com…');
   iframe.src=EMBED_URL;
   loadTimeout=setTimeout(()=>{
     loadTimeout=null;
     setState('Kalender belum merespons. Coba muat ulang atau gunakan kalender sebelumnya.');
   },18000);
 }
 iframe.addEventListener('load',()=>{
   cancelTimer();
   setState('Pemuatan iframe selesai. Jika kalender kosong, gunakan Muat ulang atau Kalender sebelumnya.');
 });
 iframe.addEventListener('error',()=>{
   cancelTimer();
   setState('Gagal memuat Investing.com. Gunakan tombol Kalender sebelumnya.');
 });
 section.querySelector('#mm-investing-calendar-reload').addEventListener('click',loadFrame);
 section.querySelector('#mm-investing-calendar-legacy').addEventListener('click',()=>{
   cancelTimer();
   document.body.classList.add('mm-investing-calendar-fallback');
   document.body.classList.remove('mm-investing-calendar-on');
 });
 loadFrame();
 return section;
}
let lastShell=null,pending=false;
function mount(){
 const active=isCalendar();
 const shell=active?document.querySelector('section.mm88-desk'):null;
 if(!shell){
   lastShell=null;
   document.body.classList.remove('mm-investing-calendar-on','mm-investing-calendar-fallback');
   return;
 }
 if(document.body.classList.contains('mm-investing-calendar-fallback'))return;
 document.body.classList.add('mm-investing-calendar-on');
 if(shell===lastShell && shell.querySelector('#mm-investing-calendar'))return;
 if(!shell.querySelector('#mm-investing-calendar'))shell.prepend(createCalendar());
 lastShell=shell;
}
function queue(){if(pending)return;pending=true;requestAnimationFrame(()=>{pending=false;mount();});}
function start(){
 queue();
 document.addEventListener('click',event=>{if(event.target.closest&&event.target.closest('.navbtn,[data-page="Kalender Ekonomi"]'))queue();});
 const root=document.getElementById('app')||document.body;
 new MutationObserver(queue).observe(root,{childList:true,subtree:true});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',start,{once:true});else start();
})();`;

function injectInvestingCalendar(html,rawUrl=process.env.MM_INVESTING_CALENDAR_URL){
  if(typeof html!=='string'||!/<\/head\s*>/i.test(html)||!/<\/body\s*>/i.test(html))return html;
  const url=approvedInvestingUrl(rawUrl);
  if(!url||html.includes('id="'+SCRIPT_ID+'"'))return html;
  const safe=JSON.stringify(url).replace(/</g,'\\u003c').replace(/>/g,'\\u003e');
  const script='<script id="'+SCRIPT_ID+'" data-release="'+RELEASE+'">'+CLIENT.replace('__MM_IFRAME_URL__',safe)+'</script>';
  return html.replace(/<\/head\s*>/i,STYLE+'</head>').replace(/<\/body\s*>/i,script+'</body>');
}
module.exports={RELEASE,approvedInvestingUrl,injectInvestingCalendar,STYLE,CLIENT};